#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;

vector<long long> parts(const string& v) {
    vector<long long> out;
    string cur;
    for (char ch : v) {
        if (ch == '.') {
            out.push_back(stoll(cur));
            cur = "";
        } else {
            cur += ch;
        }
    }
    out.push_back(stoll(cur));
    return out;
}

int main() {
    string a;
    cin >> a;
    string b;
    cin >> b;

    vector<long long> x = parts(a), y = parts(b);
    int result = 0;
    for (size_t i = 0; i < max(x.size(), y.size()); i++) {
        long long p = i < x.size() ? x[i] : 0;
        long long q = i < y.size() ? y[i] : 0;
        if (p != q) {
            result = p > q ? 1 : -1;
            break;
        }
    }
    cout << result << "\n";

    return 0;
}

